import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const CoverLetterPage = ({ userToken, userObject }) => {
    const [jobDescription, setJobDescription] = useState("");
    const [coverLetter, setCoverLetter] = useState("");
    const navigate = useNavigate();

    const generateCoverLetter = async () => {
        if (!jobDescription) {
            alert("Please enter a job description.");
            return;
        }
        const cleanedResumeData = {
            name: userObject.name || "N/A",
            email: userObject.email || "N/A",
            phone: userObject.phone || "N/A",
            website: userObject.website || "N/A",
            experience: Array.isArray(userObject.experience) ? userObject.experience : [],
            projects: Array.isArray(userObject.projects) ? userObject.projects : [],
            skills: Array.isArray(userObject.skills) ? userObject.skills : [],
            certifications: Array.isArray(userObject.certifications) ? userObject.certifications : [],
            degrees: Array.isArray(userObject.degrees) ? userObject.degrees : [],
        };

        console.log("Sending Resume Data:", cleanedResumeData);

        try {
            const response = await fetch("/api/generate-cover-letter", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${userToken}`,
                },
                body: JSON.stringify({ resumeData: userObject, jobDescription }),
            });

            if (response.ok) {
                const data = await response.json();
                setCoverLetter(data.coverLetter);
            } else {
                alert("Failed to generate cover letter.");
            }
        } catch (error) {
            console.error("Error generating cover letter:", error);
        }
    };

    return (
        <div style={{ padding: "20px" }}>
            <h1>Generate a Tailored Cover Letter</h1>

            {/* Back to Resume Button */}
            <button onClick={() => navigate("/")} style={{ marginBottom: "20px" }}>
                Back to Resume
            </button>

            <textarea
                placeholder="Paste the job description here..."
                value={jobDescription}
                onChange={(e) => setJobDescription(e.target.value)}
                style={{ width: "100%", height: "150px", marginBottom: "10px" }}
            />

            <button onClick={generateCoverLetter} style={{ marginBottom: "20px" }}>
                Generate Cover Letter
            </button>

            {coverLetter && (
                <div>
                    <h2>Your Tailored Cover Letter</h2>
                    <textarea
                        value={coverLetter}
                        onChange={(e) => setCoverLetter(e.target.value)}
                        style={{ width: "100%", height: "300px" }}
                    />
                    {/*
                    <button onClick={() => saveCoverLetter(userToken, coverLetter)}>
                        Save Cover Letter
                    </button>
                    */}
                </div>
            )}
        </div>
    );
};

export default CoverLetterPage;
